package com.bookeat.wallet.controller;
import com.bookeat.common.response.*;import com.bookeat.security.AppPrincipal;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.access.prepost.PreAuthorize;import lombok.RequiredArgsConstructor;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import java.util.*;
@RestController @RequiredArgsConstructor @SecurityRequirement(name="bearerAuth")
public class WalletController {
private final com.bookeat.wallet.service.WalletService service;private final com.bookeat.wallet.service.WalletServiceImpl implementation;private final com.bookeat.wallet.service.AdminWalletService admin;
 @GetMapping("/api/v1/customer/wallet") @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="Load own wallet",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.wallet.dto.WalletResponses.Balance> op0(@AuthenticationPrincipal AppPrincipal p){return ApiResponse.ok("Load own wallet",service.balance(p.userId()));}
 @GetMapping("/api/v1/customer/rewards") @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="Load own rewards",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.wallet.dto.WalletResponses.Balance> op1(@AuthenticationPrincipal AppPrincipal p){return ApiResponse.ok("Load own rewards",service.balance(p.userId()));}
 @GetMapping("/api/v1/customer/wallet/transactions") @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="Load own wallet/transactions",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<PageResponse<com.bookeat.wallet.dto.WalletResponses.Entry>> op2(@AuthenticationPrincipal AppPrincipal p,@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){return ApiResponse.ok("Load own wallet/transactions",service.history(p.userId(),page,size));}
 @GetMapping("/api/v1/customer/rewards/history") @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="Load own rewards/history",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<PageResponse<com.bookeat.wallet.dto.WalletResponses.Entry>> op3(@AuthenticationPrincipal AppPrincipal p,@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){return ApiResponse.ok("Load own rewards/history",service.history(p.userId(),page,size));}
 @GetMapping("/api/v1/customer/rewards/how-to-earn") @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="List active reward rules",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<List<com.bookeat.wallet.dto.WalletResponses.Rule>> op4(@AuthenticationPrincipal AppPrincipal p){return ApiResponse.ok("List active reward rules",service.rules());}
 @PostMapping("/api/v1/customer/rewards/calculate-redemption") @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="Calculate reward conversion on server",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.wallet.dto.WalletResponses.Redemption> op5(@AuthenticationPrincipal AppPrincipal p,@Valid @RequestBody com.bookeat.wallet.dto.WalletRequests.Redemption q){return ApiResponse.ok("Calculate reward conversion on server",service.calculate(p.userId(),q.points()));}
 @PostMapping("/api/v1/customer/rewards/redeem") @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="Redeem points to wallet exactly once",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.wallet.dto.WalletResponses.Balance> op6(@AuthenticationPrincipal AppPrincipal p,@RequestHeader("Idempotency-Key") String key,@Valid @RequestBody com.bookeat.wallet.dto.WalletRequests.Redemption q){return ApiResponse.ok("Redeem points to wallet exactly once",service.redeem(p.userId(),key,q));}
 @PostMapping("/api/v1/customer/rewards/claim") @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="Claim verified spend, first-booking or review reward",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.wallet.dto.WalletResponses.Balance> op7(@AuthenticationPrincipal AppPrincipal p,@RequestHeader("Idempotency-Key") String key,@Valid @RequestBody com.bookeat.wallet.dto.WalletRequests.Claim q){return ApiResponse.ok("Claim verified spend, first-booking or review reward",service.claim(p.userId(),key,q));}
 @GetMapping("/api/v1/admin/wallets") @PreAuthorize("hasAuthority('WALLET_MANAGE')") @Operation(summary="List wallet balances",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<PageResponse<com.bookeat.wallet.service.AdminWalletService.View>> op8(@AuthenticationPrincipal AppPrincipal p,@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){return ApiResponse.ok("List wallet balances",admin.list(page,size));}
 @GetMapping("/api/v1/admin/wallets/{id}") @PreAuthorize("hasAuthority('WALLET_MANAGE')") @Operation(summary="Get customer wallet by customer profile ID",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.wallet.service.AdminWalletService.View> op9(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID id){return ApiResponse.ok("Get customer wallet by customer profile ID",admin.get(id));}
 @PostMapping("/api/v1/admin/wallets/{id}/adjust") @PreAuthorize("hasAuthority('WALLET_MANAGE')") @Operation(summary="Audit and apply manual wallet adjustment",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.wallet.dto.WalletResponses.Balance> op10(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID id,@RequestHeader("Idempotency-Key") String key,@Valid @RequestBody com.bookeat.wallet.dto.WalletRequests.Adjustment q){return ApiResponse.ok("Audit and apply manual wallet adjustment",service.adjust(p.userId(),id,key,q));}
 @PostMapping("/api/v1/admin/reward-rules") @ResponseStatus(org.springframework.http.HttpStatus.CREATED) @PreAuthorize("hasAuthority('REWARD_MANAGE')") @Operation(summary="Create configurable reward rule",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.wallet.dto.WalletResponses.Rule> op11(@AuthenticationPrincipal AppPrincipal p,@Valid @RequestBody com.bookeat.wallet.dto.WalletRequests.Rule q){return ApiResponse.ok("Create configurable reward rule",implementation.createRule(p.userId(),q));}
 @PutMapping("/api/v1/admin/reward-rules/{id}/disable") @PreAuthorize("hasAuthority('REWARD_MANAGE')") @Operation(summary="Disable reward rule",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.wallet.dto.WalletResponses.Rule> op12(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID id,@Valid @RequestBody com.bookeat.payment.dto.PaymentRequests.Action q){return ApiResponse.ok("Disable reward rule",implementation.disableRule(p.userId(),id,q.version()));}
}
